    24→    {
    25→        public const int Size = 20;
    26→        private const int HexCharsCount = 2 * Size; // 5a4eab120fb44eb6684e5e32785702ff45ea344d
    27→        private const int PrefixedHexCharsCount = 2 + HexCharsCount; // 0x5a4eab120fb44eb6684e5e32785702ff45ea344d
    28→
    29→        public static Address Zero { get; } = new(new byte[Size]);
    30→        public static Address MaxValue { get; } = new("0xffffffffffffffffffffffffffffffffffffffff");
