    43→        public static bool IsValidAddress(string hexString, bool allowPrefix)
    44→        {
    45→            if (!(hexString.Length == HexCharsCount || allowPrefix && hexString.Length == PrefixedHexCharsCount))
    46→            {
    47→                return false;
    48→            }
    49→
    50→            bool hasPrefix = hexString.Length == PrefixedHexCharsCount;
    51→            if (hasPrefix)
    52→            {
    53→                if (hexString[0] != '0' || hexString[1] != 'x')
    54→                {
    55→                    return false;
    56→                }
    57→            }
    58→
    59→            for (int i = hasPrefix ? 2 : 0; i < hexString.Length; i++)
    60→            {
    61→                char c = hexString[i];
    62→                bool isHex = (c >= '0' && c <= '9') ||
    63→                             (c >= 'a' && c <= 'f') ||
    64→                             (c >= 'A' && c <= 'F');
    65→
    66→                if (!isHex) return false;
    67→            }
    68→
    69→            return true;
    70→        }
